# %% ../nbs/API/03_analysis.ipynb #b2bf61b4
POS_CLASSES = ("A-div", "A-shared", "N-div", "invariant", "outside")
OBSERVATIONS = ("to_TR", "to_third", "indel")

TAG = {("A-div", "to_TR"): "Adiv>TR", ("A-div", "to_third"): "Adiv>3rd",
       ("A-shared", "to_third"): "Ash>3rd", ("N-div", "to_TR"): "Ndiv>TR",
       ("N-div", "to_third"): "Ndiv>3rd", ("invariant", "to_third"): "inv",
       ("outside", "to_third"): "out"}

#mutations a conversion carrying reverse-transcriptase errors can produce
DGR_CONSISTENT = {("A-div", "to_TR"), ("A-div", "to_third"),
                  ("A-shared", "to_third"), ("N-div", "to_TR")}
#mutations that are positive evidence the molecule carries TR-derived sequence
CONVERSION_EVIDENCE = {("A-div", "to_TR"), ("N-div", "to_TR")}


# %% ../nbs/API/03_analysis.ipynb #f22e9766
class TRAlignment:
    """Positional annotation of an amplicon against its template repeat.

    Two facts are kept apart, because merging them mixes *was this molecule
    converted* with *did the reverse transcriptase err here*:

    position class, a property of the reference
        `A-div`      TR=A, TR!=VR   conversion and RT fidelity, confounded
        `A-shared`   TR=VR=A        RT error only, and only if converted
        `N-div`      TR!=A, TR!=VR  conversion alone, no mutagenesis expected
        `invariant`  TR=VR!=A       nothing expected; mutations are noise
        `outside`    not covered by the TR

    observation, what the read carries
        `to_TR`, `to_third`, or `indel` (never a conversion signal)

    Note this keys on the **TR** base, not the reference base. Where the VR is
    designed to match the TR the two coincide, but at a natural DGR locus the VR
    is already a retrohoming product with its adenines spent, so the positions
    reporting a new conversion have a non-A reference base.
    """

    def __init__(self,
                 ref_seq: str,  #reference amplicon sequence
                 tr_seq: str,  #template repeat, in the same orientation as ref_seq
                 vr_start: int = None,  #0-based start of the VR; located automatically if None
                 min_identity: float = 0.5,  #identity required when locating the VR
                 ):
        ref_seq, tr_seq = ref_seq.upper(), tr_seq.upper()
        if len(tr_seq) > len(ref_seq):
            raise ValueError("tr_seq is longer than ref_seq")
        if vr_start is None:
            vr_start, ident = self._locate(ref_seq, tr_seq)
            if ident < min_identity:
                raise ValueError(f"could not locate the VR in ref_seq (best identity "
                                 f"{ident:.2f} < {min_identity}); pass vr_start explicitly")
        if not 0 <= vr_start <= len(ref_seq) - len(tr_seq):
            raise ValueError(f"vr_start={vr_start} places the TR outside ref_seq")

        self.ref_seq, self.tr_seq, self.vr_start = ref_seq, tr_seq, vr_start
        self.vr_end = vr_start + len(tr_seq)
        vr = ref_seq[vr_start:self.vr_end]
        self.vr_seq = vr

        self._cls = {}
        for i, (t, v) in enumerate(zip(tr_seq, vr)):
            p = vr_start + i
            if t == "A" and t != v:  self._cls[p] = "A-div"
            elif t == "A":           self._cls[p] = "A-shared"
            elif t != v:             self._cls[p] = "N-div"
            else:                    self._cls[p] = "invariant"
        self.positions = {c: tuple(p for p, k in sorted(self._cls.items()) if k == c)
                          for c in POS_CLASSES[:4]}
        self.outside = tuple(p for p in range(len(ref_seq))
                             if not vr_start <= p < self.vr_end)

        #position sets for the mutagenesis test, grouped by TR base.
        #The reverse transcriptase misincorporates most at TR adenines and, an
        #order of magnitude lower but still well above background, at TR
        #thymines; TR-T is therefore excluded from the test rather than used as
        #a null, and reported separately.
        self.signal_positions = self.positions["A-div"] + self.positions["A-shared"]
        self.null_positions = tuple(p for p in self.positions["invariant"]
                                    if self.tr_base(p) in ("G", "C"))
        self.thymine_positions = tuple(p for p in self.positions["invariant"]
                                       if self.tr_base(p) == "T")
        self._signal = set(self.signal_positions)
        self._null = set(self.null_positions)
        self._thy = set(self.thymine_positions)

    @staticmethod
    def _locate(ref_seq, tr_seq):
        best, best_off = -1.0, 0
        for off in range(len(ref_seq) - len(tr_seq) + 1):
            w = ref_seq[off:off + len(tr_seq)]
            ident = sum(a == b for a, b in zip(w, tr_seq)) / len(tr_seq)
            if ident > best: best, best_off = ident, off
        return best_off, best

    def position_class(self, pos: int):
        "Position class of reference position `pos`."
        return self._cls.get(pos, "outside")

    def tr_base(self, pos: int):
        "TR base aligned to reference position `pos`, or None if outside the VR."
        if self.vr_start <= pos < self.vr_end:
            return self.tr_seq[pos - self.vr_start]
        return None

    def observation(self, pos: int, ref_base: str, alt: str):
        "What the read carries at `pos`: `to_TR`, `to_third` or `indel`."
        if alt == "-" or ref_base == "-":
            return "indel"
        return "to_TR" if alt == self.tr_base(pos) else "to_third"

    def classify(self, pos: int, ref_base: str, alt: str):
        "(position class, observation) for one mutation."
        return self.position_class(pos), self.observation(pos, ref_base, alt)

    def __repr__(self):
        n = {c: len(v) for c, v in self.positions.items()}
        return (f"TRAlignment(ref={len(self.ref_seq)}bp, VR=[{self.vr_start},{self.vr_end}), "
                f"A-div={n['A-div']}, A-shared={n['A-shared']}, N-div={n['N-div']}, "
                f"invariant={n['invariant']})")


# %% ../nbs/API/03_analysis.ipynb #f619927f
def classify_genotype(genotype: str,  #genotype string, e.g. "G90A,A101G"
                      aln: TRAlignment,  #positional annotation of the amplicon
                      ):
    """Counts per (position class, observation), plus molecule-level summaries.

    `dgr_consistent` means every mutation is one a conversion carrying
    reverse-transcriptase errors could produce. `fidelity` is the fraction of
    mutations at divergent positions that carry the TR base; it is measured
    within observed events, so it needs no conversion-tract model.
    """
    counts = {}
    kA = kGC = kT = 0
    for ref_b, pos, alt in str_to_mut(genotype):
        key = aln.classify(pos, ref_b, alt)
        counts[key] = counts.get(key, 0) + 1
        if key[1] != "indel":
            if pos in aln._signal: kA += 1
            elif pos in aln._null: kGC += 1
            elif pos in aln._thy: kT += 1

    n = sum(counts.values())
    conv = sum(v for k, v in counts.items() if k in CONVERSION_EVIDENCE)
    div_mut = sum(v for k, v in counts.items() if k[0] in ("A-div", "N-div"))
    rt_err = counts.get(("A-div", "to_third"), 0) + counts.get(("A-shared", "to_third"), 0)
    unexplained = n - sum(v for k, v in counts.items() if k in DGR_CONSISTENT)
    return dict(
        n_mutations=n, counts=counts,
        conversion_evidence=conv, div_positions_mutated=div_mut, rt_errors=rt_err,
        unexplained=unexplained, dgr_consistent=bool(n) and unexplained == 0,
        fidelity=(conv / div_mut) if div_mut else float("nan"),
        k_TR_A=kA, k_TR_GC=kGC, k_TR_T=kT,
    )


# %% ../nbs/API/03_analysis.ipynb #1c2b30b3
def annotate_genotype(genotype: str,  #genotype string
                      aln: TRAlignment,  #positional annotation of the amplicon
                      sep: str = "|",  #separator between a mutation and its tag
                      ):
    """Render a genotype with each mutation tagged by class, for inspection.

    A derived view: the canonical genotype string is unchanged, stays comparable
    between analyses, and remains the key for UMI grouping. Annotated strings
    must not be used as keys.
    """
    return ",".join(f"{rb}{pos}{alt}{sep}{TAG.get(aln.classify(pos, rb, alt), 'indel')}"
                    for rb, pos, alt in str_to_mut(genotype))


# %% ../nbs/API/03_analysis.ipynb #47232c46
def calibrate_null(gen_list: list,  #(genotype, count) pairs from get_genotypes
                   aln: TRAlignment,  #positional annotation of the amplicon
                   covered: tuple = None,  #(start, end) of ref_seq the reads actually span
                   ):
    """Null probability that a noise mutation lands on a TR adenine.

    Estimated from sequence outside the VR, where neither conversion nor
    mutagenesis acts, split by base: adenines and G/C do not carry the same
    sequencing error rate, and assuming they do misstates the null badly.

    Pools per-position rates after trimming the noisiest, rather than pooling all. Off-target reads
    - failed clusters, index hopping, adapter readthrough - disagree with the
    reference almost everywhere, so the few surviving read-level filtering inflate
    whichever positions they reach. Pooling lets one such position set the rate for
    its whole base class: in the data this was built on that raised the adenine
    null threefold and reported zero DGR molecules in a sample that is ~7%
    converted.

    Returns (rate at A, rate at G/C, p0).
    """
    lo, hi = covered if covered else (0, len(aln.ref_seq))
    outA = [p for p in aln.outside if lo <= p < hi and aln.ref_seq[p] == "A"]
    outN = [p for p in aln.outside if lo <= p < hi and aln.ref_seq[p] in ("G", "C")]
    if not outA or not outN:
        raise ValueError("no flanking A and G/C positions available to calibrate the null")
    perpos = {p: 0 for p in outA + outN}
    total = sum(n for _, n in gen_list)
    for g, n in gen_list:
        for ref_b, pos, alt in str_to_mut(g):
            if alt == "-" or ref_b == "-": continue
            if pos in perpos: perpos[pos] += n

    def _trimmed_rate(positions, trim=0.1):
        # drop the noisiest positions, then pool the rest. A plain median would
        # be robust too but collapses to zero when most positions carry no
        # mutation, which is common at low depth; pooling the remainder does not.
        counts = sorted(perpos[p] for p in positions)
        keep = counts[:max(len(counts) - max(1, int(round(trim * len(counts)))), 1)]
        return (sum(keep) + 0.5) / max(len(keep) * total, 1)   # +0.5 keeps p0 finite

    rA, rN = _trimmed_rate(outA), _trimmed_rate(outN)
    nA = len([p for p in aln.signal_positions if lo <= p < hi])
    nN = len([p for p in aln.null_positions if lo <= p < hi])
    denom = nA * rA + nN * rN
    return rA, rN, (nA * rA / denom if denom else float("nan"))


# %% ../nbs/API/03_analysis.ipynb #04ced630
def _binom_sf(k: int, n: int, p: float):
    "P(X >= k) for X ~ Binomial(n, p), computed exactly."
    if k <= 0: return 1.0
    if k > n: return 0.0
    return sum(math.comb(n, i) * p**i * (1 - p)**(n - i) for i in range(k, n + 1))

def dgr_pvalue(genotype: str,  #genotype string
               aln: TRAlignment,  #positional annotation of the amplicon
               p0: float,  #null probability from calibrate_null
               ):
    """One-sided binomial tail: are this molecule's mutations concentrated on TR adenines?

    Conditions on the molecule's own mutation count, so a poor-quality molecule
    gets more trials and its adenine count is correctly less surprising. TR-T
    positions are excluded from both classes.
    """
    i = classify_genotype(genotype, aln)
    return _binom_sf(i["k_TR_A"], i["k_TR_A"] + i["k_TR_GC"], p0)


# %% ../nbs/API/03_analysis.ipynb #5cd1af3b
def find_dgr_molecules(gen_list: list,  #(genotype, count) pairs from get_genotypes
                       aln: TRAlignment,  #positional annotation of the amplicon
                       fdr: float = 0.05,  #Benjamini-Hochberg false discovery rate
                       p0: float = None,  #null probability; calibrated from gen_list if None
                       covered: tuple = None,  #(start, end) of ref_seq the reads span
                       ):
    """Search for molecules whose mutations are concentrated on TR adenines.

    Every molecule is a test and the correction runs over all of them, so a
    handful of strongly mutated molecules can be called against a background of
    millions. Returns (results, p0), results being (genotype, count, p, info)
    sorted by p, for the molecules passing the FDR threshold.
    """
    if p0 is None:
        p0 = calibrate_null(gen_list, aln, covered)[2]
    m = sum(n for _, n in gen_list)
    scored = []
    for g, n in gen_list:
        info = classify_genotype(g, aln)
        if info["k_TR_A"] + info["k_TR_GC"] < 2: continue
        scored.append((_binom_sf(info["k_TR_A"], info["k_TR_A"] + info["k_TR_GC"], p0),
                       g, n, info))
    scored.sort(key=lambda x: x[0])
    rank = cutoff = 0
    for p, g, n, info in scored:
        if p <= (rank + n) * fdr / m: cutoff = rank + n
        rank += n
    out, rank = [], 0
    for p, g, n, info in scored:
        if rank >= cutoff: break
        out.append((g, n, p, info)); rank += n
    return out, p0

